describe("custom header", () => {
  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];

  const renderCustomHeader = (params: ReactDatePickerCustomHeaderProps) => {
    const {
      date,
      visibleYearsRange,
      changeYear,
      changeMonth,
      decreaseMonth,
      increaseMonth,
      prevMonthButtonDisabled,
      nextMonthButtonDisabled,
    } = params;

    return (
      <div className="custom-header">
        {visibleYearsRange && (
          <h6 className="visible-years-range">
            {visibleYearsRange.startYear} to {visibleYearsRange.endYear}
          </h6>
        )}
        <button
          className="prevMonth"
          onClick={decreaseMonth}
          disabled={prevMonthButtonDisabled}
        >
          {"<"}
        </button>

        <select
          value={getYear(date)}
          className="year-select"
          onChange={({ target: { value } }) => changeYear(Number(value))}
        >
          {[2017, 2018, 2019].map((year) => (
            <option key={year} value={year}>
              {year}
            </option>
          ))}
        </select>

        <select
          className="month-select"
          value={months[getMonth(date)]}
          onChange={({ target: { value } }) => changeMonth(Number(value))}
        >
          {months.map((option, index) => (
            <option key={option} value={index}>
              {option}
            </option>
          ))}
        </select>

        <button
          className="nextMonth"
          onClick={increaseMonth}
          disabled={nextMonthButtonDisabled}
        >
          {"<"}
        </button>
      </div>
    );
  };

  it("should call render custom header function and returns parameters", () => {
    const renderCustomHeader = jest.fn();

    getCalendar({ renderCustomHeader });

    const match = {
